    string PageGroup(string page)=>page switch{"Dashboard" or "Price Checker" or "Deal Finder" or "FM Tracker" or "Item Catalog" or "Compare" or "Market Activity" or "Price History" or "Price Changes" or "Seller Comparison" or "Websites"=>"Market","Inventory" or "Characters" or "Transfers" or "Equipment" or "Item Notes" or "Restock" or "Undo Center"=>"Inventory","Settings" or "Backups" or "Getting Started" or "Market Health"=>"Settings",_=>"Trading"};
    void BuildUsabilityTools()
    {
        void Page(string name,DataGridView grid,string explanation,params (string,Action)[] actions){var bar=Toolbar();foreach(var (label,action) in actions)bar.Controls.Add(Button(label,action));var note=Info(72);note.Text=explanation;pages[name].Controls.Add(grid);pages[name].Controls.Add(note);pages[name].Controls.Add(bar);}
        Page("Price Changes",movementGrid,"Changes compare the latest two saved observations of the same listing and exact variant. They are asking-price changes, not market-wide returns. Unchanged repeat fetches do not create new history.",("Reload",RenderUsability),("Open listing",()=>{if(SelectedMerchant(movementGrid) is PriceMovement m)Open(m.Listing.Url);}));
        Page("Seller Comparison",sellerCompareGrid,"Compare available asking listings side by side. Exact equipment stats, last check, source time and seller stock remain visible. Different variants are shown separately; stale data is labeled.",("Compare item",RenderSellerComparison),("Open selected source",()=>{if(SelectedMerchant(sellerCompareGrid) is Observation o)Open(o.Url);}));var compareBar=Toolbar();compareBar.Controls.Add(sellerQuery);compareQuantity.Width=100;compareBar.Controls.Add(new Label(){Text="Quantity",AutoSize=true,Padding=new Padding(5,10,0,0)});compareBar.Controls.Add(compareQuantity);compareQuantity.ValueChanged+=(_,_)=>RenderSellerComparison();sellerQuery.TextChanged+=(_,_)=>RenderSellerComparison();pages["Seller Comparison"].Controls.Add(compareBar);
        Page("Undo Center",undoGrid,"Supported actions: inventory edits, watch changes, removals, imports and linked trade stock updates. Inventory undo requires the whole bag to match the saved result. Transfers, journal entries and other preferences are not undone here. Latest 200 inventory changes are retained; restoring a backup clears undo history.",("Undo selected",UndoSelectedAction),("Refresh",RenderUsability));
        Page("Profit Breakdown",profitGrid,"Based on this character's recorded journal, grouped by exact item variant. Profit uses matched FIFO purchase costs and allocated fees. Unsold cost is historical acquisition cost, not current market value; unmatched sales are excluded from profit.",("Refresh",RenderUsability),("Open journal",()=>ShowPage("Trade Journal")));pages["Profit Breakdown"].Controls.Add(profitSummary);
        var toolsBar=Toolbar();toolsBar.Controls.Add(Button("Compact companion",ShowCompact));toolsBar.Controls.Add(Button("Pin / unpin this page",()=>TogglePagePin("Dashboard")));toolsBar.Controls.Add(Button("My inventory",()=>ShowPage("Inventory")));toolsBar.Controls.Add(Button("Record trade",()=>EditTrade(null)));toolsBar.Controls.Add(Button("Switch character",()=>ShowPage("Characters")));toolsBar.Controls.Add(Button("Source health",()=>ShowPage("Market Health")));pages["Dashboard"].Controls.Add(toolsBar);
        organizedNav=navigation.Values.First().Parent as FlowLayoutPanel;foreach(var (name,button) in navigation){var menu=new ContextMenuStrip();menu.Items.Add("Pin / unpin page",null,(_,_)=>TogglePagePin(name));button.ContextMenuStrip=menu;button.Disposed+=(_,_)=>menu.Dispose();}
        FormClosed+=(_,_)=>compactWindow?.Close();usabilityReady=true;RebuildNavigation();RenderUsability();
