    void TogglePagePin(string page){if(!Workspace.PinnedPages.Remove(page))Workspace.PinnedPages.Add(page);SaveFeatures();RebuildNavigation();}
    void RebuildNavigation()
    {
        if(organizedNav is null)return;organizedNav.SuspendLayout();foreach(Control control in organizedNav.Controls.Cast<Control>().ToArray()){organizedNav.Controls.Remove(control);if(!navigation.Values.Contains(control))control.Dispose();}
        void Heading(string text){organizedNav.Controls.Add(new Label(){Text=text,Width=164,Height=25,ForeColor=Color.White,Padding=new Padding(4,7,0,0)});}
        var pinned=Workspace.PinnedPages.Where(navigation.ContainsKey).ToList();if(pinned.Count>0){Heading("PINNED");foreach(var page in pinned)organizedNav.Controls.Add(navigation[page]);}
        foreach(var group in new[]{"Market","Inventory","Trading","Settings"}){var heading=Button((collapsedGroups.Contains(group)?"+ ":"− ")+group,()=>{if(!collapsedGroups.Remove(group))collapsedGroups.Add(group);RebuildNavigation();});heading.Width=164;heading.Height=30;organizedNav.Controls.Add(heading);if(!collapsedGroups.Contains(group))foreach(var (page,button) in navigation.Where(p=>PageGroup(p.Key)==group&&!pinned.Contains(p.Key)&&(fullNavigation||expandedTools.Contains(group)||essentialPages.Contains(p.Key))))organizedNav.Controls.Add(button);}
        var more=Button(fullNavigation?"Show simple menu":"Show all tools",()=>{fullNavigation=!fullNavigation;if(!fullNavigation)expandedTools.Clear();RebuildNavigation();});more.Width=164;organizedNav.Controls.Add(more);organizedNav.ResumeLayout();
    }
    void EnsureNavigation(string name){if(!usabilityReady)return;CompactGroups(name);if(collapsedGroups.Remove(PageGroup(name)))RebuildNavigation();}
    void ExtendItemCommands(ContextMenuStrip menu,Func<object?> current)
    {
        menu.Items.Add(new ToolStripSeparator());
        menu.Items.Add("View on NiaMeowDB",null,(_,_)=>{if(current() is {} item)ShowWebsite("NiaMeowDB",ItemName(item),item);});
        menu.Items.Add("Other websites",null,(_,_)=>{if(current() is {} item)ShowItemWebsites(ItemName(item),item);});
        menu.Items.Add("Add to shopping list",null,(_,_)=>{if(current() is {} item){var name=ItemName(item);if(name.Length>0)EditShopping(new(Guid.NewGuid().ToString(),store.Profile,name,Listing(item)?.Variant??(item as SavedItem)?.Variant??"",1,0,0));}});
        menu.Items.Add("Plan a sale",null,(_,_)=>{if(current() is {} item){var name=ItemName(item);if(!store.Items().Any(i=>TextKey.Search(i.Name)==TextKey.Search(name)&&i.Quantity>0)){MessageBox.Show("Add owned stock to this character's inventory first.");return;}EditSelling(name,(item as SavedItem)?.Variant??Listing(item)?.Variant);}});
        menu.Items.Add("Transfer owned stock",null,(_,_)=>{if(current() is {} item)EditTransfer(ItemName(item),(item as SavedItem)?.Variant??Listing(item)?.Variant);});
        menu.Items.Add("Compare sellers",null,(_,_)=>{if(current() is {} item){sellerQuery.Text=ItemName(item);ShowPage("Seller Comparison");}});
    }
    ContextMenuStrip ItemCommandMenu(Func<object?> current)
    {
        var menu=new ContextMenuStrip();menu.Items.Add("Watch item",null,(_,_)=>{if(current() is {} item)WatchObject(item);});menu.Items.Add("Add / edit note",null,(_,_)=>{if(current() is {} item){var name=ItemName(item);EditMerchant("memo",features.Memos.FirstOrDefault(m=>m.Profile==store.Profile&&TextKey.Search(m.Name)==TextKey.Search(name))??new(Guid.NewGuid().ToString(),store.Profile,name,"Keep",""));}});menu.Items.Add("Item details",null,(_,_)=>{if(current() is {} item)ShowItemDetails(item);});ExtendItemCommands(menu,current);return menu;
    }
    void RenderSellerComparison()
    {
        SetColumns(sellerCompareGrid,["Seller / source","Unit ask","Stock","Total ask","Exact stats","Source time / last check","Freshness"]);if(sellerQuery.Text.Trim().Length==0)return;var now=DateTimeOffset.UtcNow;foreach(var o in EligibleObservations().Where(o=>TextKey.Search(o.Name)==TextKey.Search(sellerQuery.Text)&&o.Kind==EvidenceKind.Asking&&o.Available).OrderBy(o=>o.UnitPrice)){var n=sellerCompareGrid.Rows.Add(o.Seller+" / "+o.Provider,TextKey.Mesos(o.UnitPrice)+(o.PriceApproximate?" ≈":""),o.Quantity?.ToString("N0")??"Unknown",TextKey.Mesos(o.UnitPrice*compareQuantity.Value)+(o.Quantity<compareQuantity.Value?" • insufficient stock":""),o.Equipment?(o.VariantComplete?o.Variant:"Incomplete: "+o.Variant):"Stackable",$"{o.ObservedAt?.LocalDateTime.ToString("g")??"Unknown"}\nChecked {o.RetrievedAt.LocalDateTime:g}",ReliabilityTools.EvidenceStatus(o,true,now,settings.FreshHours));sellerCompareGrid.Rows[n].Tag=o;}sellerCompareGrid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;sellerCompareGrid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;sellerCompareGrid.Columns[4].FillWeight=180;
    }
    void RenderUsability()
    {
        if(!usabilityReady)return;SetColumns(movementGrid,["Item / seller","Previous ask","Latest ask","Change","Previous / latest check"]);foreach(var m in UsabilityTools.Changes(store.History().Where(o=>settings.Sources.Any(s=>s.Id==o.Provider&&s.Authorized)))){int n=movementGrid.Rows.Add(m.Name+" / "+m.Seller,TextKey.Mesos(m.Before),TextKey.Mesos(m.After),$"{(m.After/m.Before-1)*100:+0.0;-0.0;0}%",$"{m.PreviousCheck.LocalDateTime:g} → {m.LatestCheck.LocalDateTime:g}");movementGrid.Rows[n].Tag=m;}
        SetColumns(undoGrid,["When","Action","State"]);foreach(var change in store.InventoryChanges().Where(c=>c.Profile==store.Profile)){int n=undoGrid.Rows.Add(change.At.LocalDateTime.ToString("g"),change.Description,change.Undone?"Undone":"Available if inventory still matches");undoGrid.Rows[n].Tag=change;}foreach(var t in store.LinkedTrades().Where(t=>t.Profile==store.Profile)){int n=undoGrid.Rows.Add(t.At.LocalDateTime.ToString("g"),"Linked trade stock: "+t.Name,"Stock only; journal entry remains");undoGrid.Rows[n].Tag=t;}
        var profits=UsabilityTools.Profits(features.Trades.Where(t=>t.Profile==store.Profile));SetColumns(profitGrid,["Item / variant","Matched profit","All fees","Unsold units","Unsold cost","Unmatched sales"]);foreach(var p in profits)profitGrid.Rows.Add(p.Name+(p.Variant.Length>0?" • "+p.Variant:""),TextKey.Mesos(p.Profit),TextKey.Mesos(p.Fees),p.Unsold,TextKey.Mesos(p.Cost),p.Unmatched);profitSummary.Text=$"Matched profit: {TextKey.Mesos(profits.Sum(p=>p.Profit))} • total recorded fees: {TextKey.Mesos(profits.Sum(p=>p.Fees))}\nUnsold acquisition cost: {TextKey.Mesos(profits.Sum(p=>p.Cost))} • unmatched sold units: {profits.Sum(p=>p.Unmatched):N0}";
        foreach(var grid in new[]{movementGrid,undoGrid,profitGrid}){grid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;grid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;}RenderSellerComparison();UpdateCompact();
    }
    void UndoSelectedAction(){try{switch(SelectedMerchant(undoGrid)){case InventoryUndo u:store.UndoInventory(u.Id);break;case TradeEntry t:store.UndoStockTrade(t.Id);break;default:return;}Render();}catch(Exception e){MessageBox.Show(e.Message,"Undo not applied");}}
    void ShowCompact()
    {
        if(compactWindow is {IsDisposed:false}){compactWindow.Show();compactWindow.Activate();return;}compactWindow=new Form(){Text="Maple Market • Compact",Size=new Size(380,490),MinimumSize=new Size(330,350),StartPosition=FormStartPosition.CenterScreen,TopMost=true,BackColor=Surface,Font=new Font("Tahoma",10)};compactText=new Label(){Dock=DockStyle.Fill,Padding=new Padding(12),AutoEllipsis=true};var bar=new FlowLayoutPanel(){Dock=DockStyle.Bottom,Height=85};bar.Controls.Add(Button("Open full app",()=>{Show();WindowState=FormWindowState.Normal;Activate();}));bar.Controls.Add(Button("Alert Inbox",()=>{Show();WindowState=FormWindowState.Normal;ShowPage("Alert Inbox");Activate();}));var top=new CheckBox(){Text="Stay on top",Checked=true,AutoSize=true};top.CheckedChanged+=(_,_)=>{if(compactWindow is not null)compactWindow.TopMost=top.Checked;};bar.Controls.Add(top);compactWindow.Controls.Add(compactText);compactWindow.Controls.Add(bar);UpdateCompact();compactWindow.Show();
    }
    void UpdateCompact(){if(compactWindow is null||compactWindow.IsDisposed||compactText is null)return;var profile=store.Characters().Single(c=>c.Id==store.Profile);var goal=features.Goals.FirstOrDefault(g=>g.Profile==store.Profile);compactText.Text=profile.Name+"\n"+TextKey.Mesos(profile.Mesos)+" recorded mesos\n\n"+(goal is null?"No goal yet":goal.Name+": "+MerchantTools.Progress(profile.Mesos,goal.Target).ToString("N0")+"%")+"\n\nWATCHLIST\n"+string.Join("\n",store.Items().Where(i=>i.Watch).Take(6).Select(i=>i.Name))+"\n\nALERTS\n"+string.Join("\n",features.Inbox.Where(i=>i.Profile==store.Profile&&!i.Read).OrderByDescending(i=>i.At).Take(3).Select(i=>i.Title));}
    async Task SmokeUsability()
    {
        var before=Snapshot();
        using(var reconcile=CreateInventoryImport()){reconcile.Show(this);var input=reconcile.Controls.OfType<TextBox>().Single();input.Text="Name,Quantity\nBlue Potion,15";var buttons=reconcile.Controls.OfType<FlowLayoutPanel>().SelectMany(p=>p.Controls.OfType<Button>()).ToList();buttons.Single(b=>b.Text=="Preview").PerformClick();var grid=reconcile.Controls.OfType<DataGridView>().Single();if(grid.Columns.Count!=5||!buttons.Single(b=>b.Text=="Apply preview").Enabled)throw new Exception("Reconciliation preview failed");using var shot=new Bitmap(reconcile.Width,reconcile.Height);reconcile.DrawToBitmap(shot,new Rectangle(Point.Empty,reconcile.Size));shot.Save(Path.Combine(dataDirectory,"reconciliation-13.png"));reconcile.Close();}
        store.SaveItem(new("Usability test item",2,false,false));var change=store.InventoryChanges().First();store.UndoInventory(change.Id);if(store.Items().Any(i=>i.Name=="Usability test item"))throw new Exception("Undo failed");Workspace.PinnedPages=["Inventory","Price Checker"];RebuildNavigation();if(organizedNav!.Controls.OfType<Button>().First()!=navigation["Inventory"])throw new Exception("Pinned navigation wrong");sellerQuery.Text="Green Mushroom Cap";RenderUsability();foreach(var page in new[]{"Price Changes","Seller Comparison","Undo Center","Profit Breakdown","Inventory"}){ShowPage(page);CapturePreview(Path.Combine(dataDirectory,page.Replace(" ","-").ToLowerInvariant()+"-13.png"));}ShowCompact();using(var bitmap=new Bitmap(compactWindow!.Width,compactWindow.Height)){compactWindow.DrawToBitmap(bitmap,new Rectangle(Point.Empty,compactWindow.Size));bitmap.Save(Path.Combine(dataDirectory,"compact-13.png"));}compactWindow.Close();RestorePersonal(before);RebuildNavigation();await Task.CompletedTask;
